CREATE TABLE notification_preferences (tenant_id uuid NOT NULL, membership_id uuid NOT NULL, preferences jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT notification_preferences_pk UNIQUE(tenant_id,membership_id), CONSTRAINT notification_preferences_member_fk FOREIGN KEY(tenant_id,membership_id) REFERENCES tenant_memberships(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE push_devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, membership_id uuid NOT NULL, token varchar(500) NOT NULL, platform varchar(20) NOT NULL CHECK(platform IN ('ios','android','web')), last_seen_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, CONSTRAINT push_devices_member_fk FOREIGN KEY(tenant_id,membership_id) REFERENCES tenant_memberships(tenant_id,id) ON DELETE CASCADE, CONSTRAINT push_devices_member_token_unique UNIQUE(tenant_id,membership_id,token));
CREATE TABLE message_attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE, uploaded_by uuid NOT NULL, object_key varchar(500) NOT NULL, filename varchar(255) NOT NULL, content_type varchar(120) NOT NULL, byte_size integer NOT NULL CHECK(byte_size BETWEEN 1 AND 25000000), created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT message_attachments_uploader_fk FOREIGN KEY(tenant_id,uploaded_by) REFERENCES tenant_memberships(tenant_id,id), CONSTRAINT message_attachments_object_unique UNIQUE(tenant_id,object_key));
